// plugins/user-card/src/components/UserCard/UserCard.tsx

import React from 'react';
import { makeStyles, Avatar, Typography, Box } from '@material-ui/core';
import { InfoCard } from '@backstage/core-components';

/** Props for the {@link UserCard} component. */
export interface UserCardProps {
  /** The full display name of the user. */
  name: string;
  /** The user's role or job title. */
  role: string;
}

const useStyles = makeStyles(theme => ({
  avatar: {
    width: theme.spacing(8),
    height: theme.spacing(8),
    backgroundColor: theme.palette.primary.main,
    fontSize: theme.typography.h4.fontSize,
    marginBottom: theme.spacing(2),
  },
  name: {
    fontWeight: theme.typography.fontWeightBold,
  },
  role: {
    color: theme.palette.text.secondary,
  },
}));

/**
 * Displays a summary card for a user, showing their name and role.
 *
 * @public
 */
export const UserCard = ({ name, role }: UserCardProps): JSX.Element => {
  const classes = useStyles();

  // Use the first character of the first and last word as the avatar initials.
  const initials = name
    .split(' ')
    .filter(Boolean)
    .map(part => part[0].toUpperCase())
    .slice(0, 2)
    .join('');

  return (
    <InfoCard title="User">
      <Box display="flex" flexDirection="column" alignItems="center" p={2}>
        <Avatar className={classes.avatar} aria-label={`Avatar for ${name}`}>
          {initials}
        </Avatar>

        <Typography
          variant="h5"
          component="h2"
          className={classes.name}
          gutterBottom
        >
          {name}
        </Typography>

        <Typography variant="subtitle1" className={classes.role}>
          {role}
        </Typography>
      </Box>
    </InfoCard>
  );
};
