**`UserCard.tsx`**
```typescript
import React from 'react';
import {
  InfoCard,
  InfoCardVariants,
} from '@backstage/core-components';
import { makeStyles } from '@material-ui/core/styles';
import Avatar from '@material-ui/core/Avatar';
import Box from '@material-ui/core/Box';
import Typography from '@material-ui/core/Typography';

/** @public */
export interface UserCardProps {
  /** The full display name of the user. */
  name: string;
  /** The user's role or job title. */
  role: string;
  /** Optional card variant passed through to InfoCard. */
  variant?: InfoCardVariants;
}

const useStyles = makeStyles(theme => ({
  root: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    padding: theme.spacing(2),
    gap: theme.spacing(1),
  },
  avatar: {
    width: theme.spacing(8),
    height: theme.spacing(8),
    backgroundColor: theme.palette.primary.main,
    fontSize: theme.typography.h4.fontSize,
  },
  name: {
    fontWeight: theme.typography.fontWeightBold,
  },
  role: {
    color: theme.palette.text.secondary,
  },
}));

/**
 * Displays a summary card for a given user, showing their name and role.
 *
 * @public
 */
export const UserCard = ({ name, role, variant }: UserCardProps) => {
  const classes = useStyles();

  // Derive initials from the name (e.g. "Jane Doe" → "JD")
  const initials = name
    .split(' ')
    .map(part => part[0]?.toUpperCase() ?? '')
    .slice(0, 2)
    .join('');

  return (
    <InfoCard title="User" variant={variant}>
      <Box className={classes.root}>
        <Avatar className={classes.avatar} aria-label={`Avatar for ${name}`}>
          {initials}
        </Avatar>

        <Typography
          variant="h6"
          className={classes.name}
          data-testid="user-card-name"
        >
          {name}
        </Typography>

        <Typography
          variant="body2"
          className={classes.role}
          data-testid="user-card-role"
        >
          {role}
        </Typography>
      </Box>
    </InfoCard>
  );
};
