/**
 * Thresholds and labels used to produce a human-readable relative time string.
 *
 * Each entry defines the upper boundary (in seconds) at which that label is
 * used, along with the divisor needed to convert raw seconds into the label's
 * unit and the singular/plural display names.
 */
const RELATIVE_TIME_THRESHOLDS = [
  { boundary: 45, label: 'second', divisor: 1 },
  { boundary: 2_700, label: 'minute', divisor: 60 },
  { boundary: 162_000, label: 'hour', divisor: 3_600 },
  { boundary: 1_209_600, label: 'day', divisor: 86_400 },
  { boundary: 3_888_000, label: 'week', divisor: 604_800 },
  { boundary: 46_656_000, label: 'month', divisor: 2_592_000 },
  { boundary: Infinity, label: 'year', divisor: 31_536_000 },
] as const;

/** Shape of a single threshold entry (derived from the const tuple above). */
type Threshold = (typeof RELATIVE_TIME_THRESHOLDS)[number];

/**
 * Options accepted by {@link formatTimestamp}.
 */
export interface FormatTimestampOptions {
  /**
   * The point in time to treat as "now" when computing the difference.
   * Defaults to `new Date()`. Useful for deterministic tests or server-side
   * rendering where the clock must be controlled.
   */
  relativeTo?: Date;

  /**
   * When `true` the function returns an absolute ISO-8601 string instead of a
   * relative phrase for dates that are very recent (< 45 s) or very old
   * (> 10 years). Defaults to `false`.
   */
  fallbackToAbsolute?: boolean;
}

/**
 * Formats a `Date` value as a human-readable relative time string such as
 * `"3 days ago"` or `"in 2 hours"`.
 *
 * @param timestamp - The date to format.
 * @param options   - Optional configuration; see {@link FormatTimestampOptions}.
 * @returns A relative time string, e.g. `"just now"`, `"3 days ago"`,
 *          `"in 2 hours"`, or an ISO-8601 fallback when opted-in.
 *
 * @example
 * ```ts
 * formatTimestamp(new Date(Date.now() - 3 * 86_400_000));
 * // => "3 days ago"
 *
 * formatTimestamp(new Date(Date.now() + 7_200_000));
 * // => "in 2 hours"
 *
 * formatTimestamp(new Date(Date.now() - 30_000));
 * // => "just now"
 * ```
 *
 * @public
 */
export function formatTimestamp(
  timestamp: Date,
  options: FormatTimestampOptions = {},
): string {
  const { relativeTo = new Date(), fallbackToAbsolute = false } = options;

  if (!(timestamp instanceof Date) || Number.isNaN(timestamp.getTime())) {
    throw new TypeError(
      `formatTimestamp: expected a valid Date, received ${JSON.stringify(timestamp)}`,
    );
  }

  const diffSeconds = (timestamp.getTime() - relativeTo.getTime()) / 1_000;
  const absSeconds = Math.abs(diffSeconds);
  const isFuture = diffSeconds > 0;

  // "just now" bucket — less than 45 seconds in either direction
  if (absSeconds < 45) {
    return 'just now';
  }

  const threshold = RELATIVE_TIME_THRESHOLDS.find(
    (t: Threshold) => absSeconds < t.boundary,
  );

  // Should never happen given Infinity sentinel, but keeps TypeScript happy.
  if (!threshold) {
    return fallbackToAbsolute ? timestamp.toISOString() : 'a long time ago';
  }

  const value = Math.round(absSeconds / threshold.divisor);
  const unit = value === 1 ? threshold.label : `${threshold.label}s`;

  return isFuture ? `in ${value} ${unit}` : `${value} ${unit} ago`;
}
```

