/**
 * Formats a Date (or ISO-8601 string / epoch ms) as a human-readable
 * relative time string, e.g. "3 days ago" or "in 2 hours".
 *
 * Uses the built-in `Intl.RelativeTimeFormat` API so no extra runtime
 * dependencies are required.
 *
 * @public
 */

/** Units understood by Intl.RelativeTimeFormat, ordered largest → smallest. */
const RELATIVE_TIME_THRESHOLDS: ReadonlyArray<{
  unit: Intl.RelativeTimeFormatUnit;
  seconds: number;
}> = [
  { unit: 'year', seconds: 365 * 24 * 60 * 60 },
  { unit: 'month', seconds: 30 * 24 * 60 * 60 },
  { unit: 'week', seconds: 7 * 24 * 60 * 60 },
  { unit: 'day', seconds: 24 * 60 * 60 },
  { unit: 'hour', seconds: 60 * 60 },
  { unit: 'minute', seconds: 60 },
  { unit: 'second', seconds: 1 },
];

/** Options accepted by {@link formatTimestamp}. */
export interface FormatTimestampOptions {
  /**
   * BCP 47 locale tag used for formatting (defaults to `'en'`).
   * @example 'fr', 'de', 'pt-BR'
   */
  locale?: string;

  /**
   * `Intl.RelativeTimeFormat` numeric option.
   * - `'auto'`   → "yesterday", "last month", … when possible  *(default)*
   * - `'always'` → "1 day ago", "1 month ago", … always numeric
   */
  numeric?: Intl.RelativeTimeFormatOptions['numeric'];

  /**
   * Treat this value as "now" instead of `Date.now()`.
   * Useful for deterministic tests.
   */
  now?: Date | number;
}

/**
 * Formats a timestamp as a relative time string.
 *
 * @param timestamp - The point in time to describe. Accepts a `Date`,
 *   an ISO-8601 string, or a Unix epoch in milliseconds.
 * @param options   - Optional locale, numeric style, and clock override.
 * @returns A localised relative time string such as `"3 days ago"`.
 *
 * @example
 * ```ts
 * formatTimestamp(new Date(Date.now() - 3 * 86_400_000)); // "3 days ago"
 * formatTimestamp('2024-01-01T00:00:00Z', { locale: 'fr' }); // "il y a X …"
 * ```
 *
 * @public
 */
export function formatTimestamp(
  timestamp: Date | string | number,
  options: FormatTimestampOptions = {},
): string {
  const { locale = 'en', numeric = 'auto', now } = options;

  const targetMs =
    timestamp instanceof Date
      ? timestamp.getTime()
      : typeof timestamp === 'string'
        ? Date.parse(timestamp)
        : timestamp;

  if (Number.isNaN(targetMs)) {
    throw new TypeError(
      `formatTimestamp: could not parse timestamp "${timestamp}"`,
    );
  }

  const nowMs = now instanceof Date ? now.getTime() : (now ?? Date.now());
  const diffSeconds = Math.round((targetMs - nowMs) / 1_000);

  const formatter = new Intl.RelativeTimeFormat(locale, {
    numeric,
    style: 'long',
  });

  // Walk thresholds from largest unit to smallest and return the first match.
  for (const { unit, seconds } of RELATIVE_TIME_THRESHOLDS) {
    if (Math.abs(diffSeconds) >= seconds || unit === 'second') {
      const value = Math.round(diffSeconds / seconds);
      return formatter.format(value, unit);
    }
  }

  // Unreachable — the loop always exits at 'second'.
  /* istanbul ignore next */
  return formatter.format(diffSeconds, 'second');
}
