 * ```ts
 * formatTimestamp(new Date(Date.now() - 3 * 24 * 60 * 60 * 1000));
 * // → '3 days ago'
 *
 * formatTimestamp(new Date(Date.now() + 60 * 1000), { locale: 'de' });
 * // → 'in 1 Minute'
 *
 * formatTimestamp(yesterday, { numeric: 'auto' });
 * // → 'yesterday'
 * ```
 *
 * @param date    - The point in time to describe.
 * @param options - Optional locale, reference date, and numeric style.
 * @returns A human-readable relative time string.
 *
 * @public
 */
export function formatTimestamp(
  date: Date,
  options: FormatTimestampOptions = {},
): string {
  const { locale, relativeTo = new Date(), numeric = 'always' } = options;

  const formatter = new Intl.RelativeTimeFormat(locale, {
    style: 'long',
    numeric,
  });

  // Positive = date is in the past; negative = date is in the future.
  const elapsedSeconds = (relativeTo.getTime() - date.getTime()) / 1_000;
  const absElapsed = Math.abs(elapsedSeconds);

  const threshold =
    THRESHOLDS.find(t => absElapsed < t.ceiling) ??
    THRESHOLDS[THRESHOLDS.length - 1];

  // Round toward zero so '89 seconds' → '1 minute', not '2 minutes'.
  const value = Math.round(elapsedSeconds / threshold.divisor);

  // RelativeTimeFormat expects a negative value for future dates.
  return formatter.format(-value, threshold.unit);
}
