 * @example
 * ```ts
 * import { formatTimestamp } from '../utils';
 *
 * formatTimestamp(new Date(Date.now() - 1000 * 60 * 5));
 * // → "5 minutes ago"
 *
 * formatTimestamp(new Date(Date.now() + 1000 * 60 * 60 * 2), { allowFuture: true });
 * // → "in 2 hours"
 * ```
 */
export function formatTimestamp(
  date: Date,
  options: FormatTimestampOptions = {},
): string {
  const { relativeTo = new Date(), allowFuture = false } = options;

  const elapsedMs = date.getTime() - relativeTo.getTime();

  // Treat future timestamps as "just now" unless the caller opts in.
  if (elapsedMs > 0 && !allowFuture) {
    return 'just now';
  }

  const formatter = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });

  return formatWithBestUnit(elapsedMs / 1_000, formatter);
