// ---------------------------------------------------------------------------

/** Ordered largest-to-smallest so we always pick the most meaningful unit. */
const THRESHOLDS: ReadonlyArray<{
  unit: Intl.RelativeTimeFormatUnit;
  seconds: number;
}> = [
  { unit: 'year',   seconds: 60 * 60 * 24 * 365 },
  { unit: 'month',  seconds: 60 * 60 * 24 * 30  },
  { unit: 'week',   seconds: 60 * 60 * 24 * 7   },
  { unit: 'day',    seconds: 60 * 60 * 24        },
  { unit: 'hour',   seconds: 60 * 60             },
  { unit: 'minute', seconds: 60                  },
  { unit: 'second', seconds: 1                   },
];

function formatWithBestUnit(
  elapsedSeconds: number,
  formatter: Intl.RelativeTimeFormat,
): string {
  const absSeconds = Math.abs(elapsedSeconds);

  for (const { unit, seconds } of THRESHOLDS) {
    if (absSeconds >= seconds) {
      // Truncate toward zero: 89 s → "1 minute", not "2 minutes".
      const value = Math.trunc(elapsedSeconds / seconds);
      return formatter.format(value, unit);
    }
  }

  return formatter.format(0, 'second'); // sub-second → "now"
}
