export interface FormatTimestampOptions {
  /**
   * The reference point to calculate relative time from.
   * Defaults to `new Date()` (now).
   */
  relativeTo?: Date;

  /**
   * Locale passed to `Intl.RelativeTimeFormat`.
   * Defaults to `'en'`.
   */
  locale?: string | string[];

  /**
   * The `numeric` option passed to `Intl.RelativeTimeFormat`.
   * - `'always'`  → "1 day ago"
   * - `'auto'`    → "yesterday"
   * Defaults to `'auto'`.
   */
  numeric?: Intl.RelativeTimeFormatNumeric;
}

/** Ordered list of thresholds used to pick the best unit. */
const DIVISIONS: { amount: number; unit: Intl.RelativeTimeFormatUnit }[] = [
  { amount: 60, unit: 'seconds' },
  { amount: 60, unit: 'minutes' },
  { amount: 24, unit: 'hours' },
  { amount: 7, unit: 'days' },
  { amount: 4, unit: 'weeks' },
  { amount: 12, unit: 'months' },
  { amount: Number.POSITIVE_INFINITY, unit: 'years' },
];

/**
 * Formats a `Date` as a human-readable relative time string.
 *
 * @example
 * ```ts
 * formatTimestamp(new Date(Date.now() - 3 * 86_400_000));
 * // → '3 days ago'
 *
 * formatTimestamp(new Date(Date.now() + 60_000));
 * // → 'in 1 minute'
 * ```
 *
 * @param date    - The date to format.
 * @param options - Optional configuration (locale, reference time, numeric style).
 * @returns A locale-aware relative time string.
 */
export function formatTimestamp(
  date: Date,
  options: FormatTimestampOptions = {},
): string {
  const { relativeTo = new Date(), locale = 'en', numeric = 'auto' } = options;

  const formatter = new Intl.RelativeTimeFormat(locale, {
    numeric,
    style: 'long',
  });

  // Elapsed time in seconds; negative means the date is in the past.
  const elapsedSeconds = (date.getTime() - relativeTo.getTime()) / 1_000;

  let duration = elapsedSeconds;

  for (const { amount, unit } of DIVISIONS) {
    if (Math.abs(duration) < amount) {
      return formatter.format(Math.round(duration), unit);
    }
    duration /= amount;
  }

  // Unreachable, but satisfies the TypeScript return-type checker.
  return formatter.format(Math.round(duration), 'years');
}
