/**
 * Formats a `Date` as a human-readable relative time string.
 *
 * @param date - The date to format.
 * @param options - Optional configuration.
 * @returns A string such as `'just now'`, `'3 days ago'`, or `'in 2 hours'`.
 *
 * @example
 * ```typescript
 * const ts = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000);
 * formatTimestamp(ts); // → '3 days ago'
 * ```
 *
 * @public
 */
export function formatTimestamp(
  date: Date,
  options: FormatTimestampOptions = {},
): string {
  const { relativeTo = new Date() } = options;

  const deltaSeconds = Math.round(
    (relativeTo.getTime() - date.getTime()) / 1_000,
  );

  const absoluteDelta = Math.abs(deltaSeconds);

  if (absoluteDelta < 5) {
    return 'just now';
  }

  const interval = INTERVALS.find(i => absoluteDelta >= i.seconds);

  // Safety-net: absoluteDelta >= 5 so 'second' always matches before we reach
  // this point, but we handle the undefined case for type safety.
  if (!interval) {
    return 'just now';
  }

  const count = Math.floor(absoluteDelta / interval.seconds);
  const plural = count !== 1 ? `${interval.label}s` : interval.label;

  return deltaSeconds >= 0
    ? `${count} ${plural} ago`
    : `in ${count} ${plural}`;
