/**
 * Options for {@link formatTimestamp}.
 *
 * @public
 */
export interface FormatTimestampOptions {
  /**
   * The reference point used to calculate the relative time.
   * Defaults to `new Date()` (now).
   */
  relativeTo?: Date;
}

/**
 * A parsed unit of relative time.
 * @internal
 */
interface RelativeTimeUnit {
  readonly threshold: number; // seconds
  readonly singular: string;
  readonly plural: string;
}

/** @internal */
const UNITS: readonly RelativeTimeUnit[] = [
  { threshold: 60, singular: 'second', plural: 'seconds' },
  { threshold: 3_600, singular: 'minute', plural: 'minutes' },
  { threshold: 86_400, singular: 'hour', plural: 'hours' },
  { threshold: 2_592_000, singular: 'day', plural: 'days' },
  { threshold: 31_536_000, singular: 'month', plural: 'months' },
  { threshold: Infinity, singular: 'year', plural: 'years' },
];

/** @internal */
const DIVISORS: readonly number[] = [1, 60, 3_600, 86_400, 2_592_000, 31_536_000];

/**
 * Formats a `Date` object as a human-readable relative time string,
 * such as `"3 days ago"` or `"in 5 minutes"`.
 *
 * @param date - The date to format.
 * @param options - Optional configuration (see {@link FormatTimestampOptions}).
 * @returns A relative time string.
 *
 * @example
 * ```ts
 * const past = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000);
 * formatTimestamp(past); // "3 days ago"
 *
 * const future = new Date(Date.now() + 2 * 60 * 60 * 1000);
 * formatTimestamp(future); // "in 2 hours"
 * ```
 *
 * @public
 */
export function formatTimestamp(
  date: Date,
  options: FormatTimestampOptions = {},
): string {
  const { relativeTo = new Date() } = options;

  const diffSeconds = (relativeTo.getTime() - date.getTime()) / 1_000;
  const absoluteDiff = Math.abs(diffSeconds);
  const isPast = diffSeconds >= 0;

  // Find the appropriate unit bucket.
  const unitIndex = UNITS.findIndex(({ threshold }) => absoluteDiff < threshold);

  // Guard: clamp to years if somehow beyond all thresholds.
  const safeIndex = unitIndex === -1 ? UNITS.length - 1 : unitIndex;

  const divisor = DIVISORS[safeIndex];
  const value = Math.floor(absoluteDiff / divisor);

  // "just now" special case.
  if (safeIndex === 0 && value < 5) {
    return 'just now';
  }

  const { singular, plural } = UNITS[safeIndex];
  const unitLabel = value === 1 ? singular : plural;

  return isPast ? `${value} ${unitLabel} ago` : `in ${value} ${unitLabel}`;
}
