```typescript
import { DateTime } from 'luxon';

/**
 * Converts an ISO 8601 timestamp string into a human-readable relative time string.
 *
 * @param isoTimestamp - A valid ISO 8601 timestamp string (e.g. "2024-01-15T10:30:00Z")
 * @returns A human-readable relative time string (e.g. "3 days ago"), or
 *          "Invalid date" if the input cannot be parsed.
 *
 * @example
 * humanReadableRelativeTime("2024-01-12T08:00:00Z"); // "3 days ago"
 * humanReadableRelativeTime("2024-01-15T12:00:00Z"); // "in 2 hours"
 * humanReadableRelativeTime("not-a-date");           // "Invalid date"
 */
export function humanReadableRelativeTime(isoTimestamp: string): string {
  const parsed = DateTime.fromISO(isoTimestamp);

  if (!parsed.isValid) {
    return 'Invalid date';
  }

  const relative = parsed.toRelative();

  // toRelative() can return null when the diff is indeterminate,
  // so we guard against that case explicitly.
  if (relative === null) {
    return 'Invalid date';
  }

  return relative;
}
```

