export function humanizeTimestamp(
  timestamp: string | null | undefined,
  options: HumanizeTimestampOptions = {},
): string {
  const { locale, fallback = 'unknown' } = options;

  if (!timestamp) {
    return fallback;
  }

  const parsed = DateTime.fromISO(timestamp, { locale });

  if (!parsed.isValid) {
    return fallback;
  }

  return parsed.toRelative({ locale }) ?? fallback;
