```typescript
// src/utils/relativeTime.ts

import { DateTime } from 'luxon';

/**
 * Converts an ISO 8601 timestamp string into a human-readable relative time
 * string (e.g. "3 days ago", "in 5 minutes", "just now").
 *
 * @param isoTimestamp - A valid ISO 8601 datetime string
 * @returns A human-readable relative time string
 * @throws {Error} If the provided string is not a valid ISO 8601 timestamp
 *
 * @example
 * formatRelativeTime('2024-01-10T12:00:00Z'); // "3 days ago"
 * formatRelativeTime('2024-01-13T14:30:00Z'); // "in 2 hours"
 */
export function formatRelativeTime(isoTimestamp: string): string {
  const parsed = DateTime.fromISO(isoTimestamp, { setZone: true });

  if (!parsed.isValid) {
    throw new Error(
      `Invalid ISO 8601 timestamp: "${isoTimestamp}". Reason: ${parsed.invalidReason}`,
    );
  }

  const relative = parsed.toRelative();

  if (!relative) {
    throw new Error(
      `Could not compute relative time for timestamp: "${isoTimestamp}"`,
    );
  }

  return relative;
}
