Here's a clean implementation using the `@backstage/core-components` ecosystem conventions. Backstage itself uses `luxon` internally, so we'll use that — it's already a transitive dependency in most Backstage setups.

```typescript
import { DateTime } from 'luxon';

/**
 * Converts an ISO 8601 timestamp string into a human-readable relative time string.
 *
 * @param isoTimestamp - A valid ISO 8601 timestamp, e.g. "2024-01-15T10:30:00.000Z"
 * @returns A human-readable relative time string, e.g. "3 days ago", "in 2 hours"
 * @throws Error if the provided string is not a valid ISO 8601 timestamp
 *
 * @example
 * formatRelativeTime('2024-01-15T10:30:00.000Z'); // "3 days ago"
 * formatRelativeTime(new Date(Date.now() - 5000).toISOString()); // "5 seconds ago"
 */
export function formatRelativeTime(isoTimestamp: string): string {
  const parsed = DateTime.fromISO(isoTimestamp);

  if (!parsed.isValid) {
    throw new Error(
      `Invalid ISO 8601 timestamp: "${isoTimestamp}". Reason: ${parsed.invalidReason}`,
    );
  }

  const relative = parsed.toRelative();

  if (!relative) {
    throw new Error(
      `Could not compute relative time for timestamp: "${isoTimestamp}"`,
    );
  }

  return relative;
}
```

### Usage in a Backstage component

```typescript
import React from 'react';
import { formatRelativeTime } from './formatRelativeTime';

type Props = {
  createdAt: string; // ISO 8601
};

export const EntityTimestamp = ({ createdAt }: Props) => {
  const label = formatRelativeTime(createdAt);

  return (
    <span title={createdAt} aria-label={`Created ${label}`}>
      {label}
    </span>
  );
};
```

